INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('f04887e6-07ea-57b9-b985-74c9efd04da4','TEXT','The Tiny Ferry — A Different Day','When Sienna first became interested in the model ferry, the task at the river workshop looked routine. Yet on Wednesday, an unexpected problem appeared. A hurried solution would have been possible, but Sienna suspected that the first explanation was too simple. Instead, Sienna treated the problem as a small investigation.
